using Cosmos.API.Security;using Cosmos.Application.Abstractions.Services;using Cosmos.Application.PurchaseExpense;using Cosmos.Domain.Security;using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Mvc;
namespace Cosmos.API.Controllers;
[Authorize,Tags("PurchaseOrdersController"),ApiExplorerSettings(GroupName="Purchase & Expense"),Route("api/purchase-orders")]
public sealed class PurchaseOrdersController(IPurchaseExpenseService s):ApiControllerBase { [HttpGet,RequirePermission("PurchaseExpense.PurchaseOrder",PermissionAction.View)]public async Task<IActionResult>List([FromQuery]PurchaseOrderListQuery q,CancellationToken ct)=>FromResponse(await s.GetPurchaseOrdersAsync(q,ct));[HttpGet("{id:long:min(1)}"),RequirePermission("PurchaseExpense.PurchaseOrder",PermissionAction.View)]public async Task<IActionResult>Get(long id,CancellationToken ct)=>FromResponse(await s.GetPurchaseOrderAsync(id,ct));[HttpPost,RequirePermission("PurchaseExpense.PurchaseOrder",PermissionAction.Create)]public async Task<IActionResult>Create(CreatePurchaseOrderRequest r,CancellationToken ct)=>FromResponse(await s.CreatePurchaseOrderAsync(r,ct),201);[HttpPut("{id:long:min(1)}"),RequirePermission("PurchaseExpense.PurchaseOrder",PermissionAction.Edit)]public async Task<IActionResult>Update(long id,UpdatePurchaseOrderRequest r,CancellationToken ct)=>FromResponse(await s.UpdatePurchaseOrderAsync(id,r,ct));[HttpDelete("{id:long:min(1)}"),RequirePermission("PurchaseExpense.PurchaseOrder",PermissionAction.Delete)]public async Task<IActionResult>Delete(long id,CancellationToken ct)=>FromResponse(await s.DeletePurchaseOrderAsync(id,ct));[HttpPost("{id:long:min(1)}/cancel"),RequirePermission("PurchaseExpense.PurchaseOrder",PermissionAction.Delete)]public async Task<IActionResult>Cancel(long id,CancellationToken ct)=>FromResponse(await s.CancelPurchaseOrderAsync(id,ct));[HttpPost("{id:long:min(1)}/convert-to-purchase-bill"),RequirePermission("PurchaseExpense.PurchaseOrder",PermissionAction.Approve)]public async Task<IActionResult>Convert(long id,ConvertPurchaseOrderRequest r,CancellationToken ct)=>FromResponse(await s.ConvertPurchaseOrderAsync(id,r,ct)); }
